button, a, [role='button'] {
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent; /* 前提：有自己的 :active 样式 */
}

const prev = item.starred
item.starred = !prev
try { await api.star(item.id, item.starred) } catch (e) { item.starred = prev; message.error('收藏没有成功，已恢复') }

const router = createRouter({
  history: createWebHistory(),
  routes,
  scrollBehavior: (_to, _from, saved) => saved ?? { top: 0 },
})

.std-reveal-actions { opacity: 1; transition: opacity .1s; }
@media (hover: hover) {
  .std-reveal-row .std-reveal-actions { opacity: 0; }
  .std-reveal-row:hover .std-reveal-actions,
  .std-reveal-row:focus-within .std-reveal-actions { opacity: 1; }
}

@media print {
  nav, .toolbar { display: none; }
  thead { display: table-header-group; }
  tr { break-inside: avoid; }
}

window.addEventListener('message', (event) => {
  if (!TRUSTED_ORIGINS.includes(event.origin)) return
  const message = parseWidgetMessage(event.data)
})

let refreshing: Promise<void> | null = null
async function onUnauthorized() {
  refreshing ??= api.refresh().finally(() => { refreshing = null })
  await refreshing
}

const channel = new BroadcastChannel('auth')
channel.onmessage = (event) => { if (event.data === 'logout') clearSession() }
export function logout() { clearSession(); channel.postMessage('logout') }

router.onError((error, to) => {
  if (/Failed to fetch dynamically imported module|Loading chunk/.test(String(error)) && !sessionStorage.getItem('chunk-reload')) {
    sessionStorage.setItem('chunk-reload', '1')
    window.location.assign(to.fullPath)
  }
})

const submitting = ref(false)
async function submit() {
  if (submitting.value) return
  submitting.value = true
  try { await api.createOrder(form, { idempotencyKey }) } finally { submitting.value = false }
}
